# korean_ttf.map — 공용
[hires]
scale=3
alpha=true

[hires:v2]
scale=2             ; v2 는 2배 (16px 픽셀 폰트에 맞춤)

[fonts]
default=fonts/NanumJangMiCe.ttf     ; v3+ 가변폭

[fonts:v2]
default=fonts/neodgm.ttf            ; v2 픽셀 폰트

[sizes]
default=12pt
title=16pt

[sizes:v2]
default=16

[render]
mode=string

[render:v2]
mode=char

[map]
height_8=default
height_9=default
height_12=title

[map:indy4]
height_16=title

[map:maniac]
height_8=default
